begin
 if (select count(*) from public.lessons) <> jsonb_array_length(expected) or exists (
  select 1 from jsonb_array_elements(expected) e left join public.lessons l on l.id=e->>'id'
  where l.id is null or l.updated_at <> (e->>'updated_at')::timestamptz or l.status <> e->>'status'
 ) then raise exception 'Curriculum publication aborted: course records changed since the review snapshot'; end if;
 if exists (
  select 1 from jsonb_array_elements(expected_config) e left join public.app_config c on c.key=e->>'key'
  where c.key is null or c.updated_at <> (e->>'updated_at')::timestamptz
 ) then raise exception 'Curriculum publication aborted: configuration changed since the review snapshot'; end if;
 for row in select value from jsonb_array_elements(patches) loop
  insert into public.review_events(lesson_id,kind,payload)
  select l.id,'curriculum_metadata_review',jsonb_build_object('request','2026-10-05 title and sequence review','before_status',l.status,'before',jsonb_build_object('title',l.data->'title','subject',l.data->'subject','level',l.data->'level','tracks',l.data->'tracks','coming_soon',l.data->'coming_soon'),'after',row->'data','review_scope','Titles, classification and ordering only; no content or scholarly approval')
  from public.lessons l where l.id=row->>'id';
  update public.lessons set status=row->>'status',data=data||(row->'data'),updated_at=clock_timestamp() where id=row->>'id';
 end loop;
 for row in select value from jsonb_array_elements(additions) loop
  insert into public.lessons(id,status,data) values(row->>'id',row->>'status',row->'data');
  insert into public.review_events(lesson_id,kind,payload) values(row->>'id','coming_soon_created',jsonb_build_object('request','2026-10-05 title and sequence review','content_ready',false,'review_scope','Title-only catalog entry with preparation placeholder','minutes_note','1 minute refers only to the preparation placeholder, not a finished lesson estimate'));
 end loop;
 update public.app_config set data=cfg->key,updated_at=clock_timestamp() where key in ('tracks','levels','subjects');
